    "statement": "Evidence on cost-effectiveness for controlling problematic plants on peatlands is not reported.",
    "citations": []
  },
  {
    "statement": "Herbicide application in fens changed overall plant community composition.",
    "citations": [
      "1776"
    ]
  },
  {
    "statement": "Herbicide application in fens did not prevent increases in shrub cover over time.",
    "citations": [
      "1776"
    ]
  },
  {
    "statement": "Herbicide application in fens prevented increases in total plant species richness.",
    "citations": [
      "1776"
    ]
  },
