    "statement": "There are no identified studies on peatland vegetation regarding the use of covers or barriers to control problematic plants.",
    "citations": [
      "1775"
    ]
  },
  {
    "statement": "There are no identified studies on peatland vegetation regarding physically damaging problematic plants.",
    "citations": [
      "1769"
    ]
  },
  {
    "statement": "There are no identified studies on peatland vegetation regarding the use of grazing to control problematic plants.",
    "citations": [
      "1773"
    ]
  },
  {
    "statement": "Cutting or removing problematic large trees and shrubs in fens changed the plant community composition toward more open-fen characteristics.",
    "citations": [
      "1772"
    ]
  },
  {
    "statement": "In Sweden, cutting or removing problematic large trees and shrubs increased the richness and cover of fen-characteristic plants.",
    "citations": [
      "1772"
    ]
  },
  {
    "statement": "In Sweden, cutting or removing problematic large trees and shrubs increased moss and vascular plant cover.",
    "citations": [
      "1772"
    ]
  },
  {
    "statement": "A replicated USA study reported that despite cutting or removing problematic large trees and shrubs, shrub cover still increased over time.",
    "citations": [
      "1772"
    ]
  },
  {
    "statement": "A replicated USA study reported that cutting or removing problematic large trees and shrubs prevented increases in total plant species richness.",
    "citations": [
      "1772"
    ]
  },
  {
    "statement": "Cutting or mowing problematic herbaceous plants showed mixed outcomes.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "Two Swedish rich-fen studies found no significant effect on overall community composition from cutting or mowing problematic herbaceous plants.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "A UK fen meadow study found mown plots developed different communities from unmown plots.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "One Swedish study found more fen-characteristic species in mown plots, but not a higher cover of those species.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "When cutting or mowing problematic herbaceous plants, plant cover responses varied by species.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "In an Estonian bog, clipping problematic plants did not affect Sphagnum growth.",
    "citations": [
      "1770"
    ]
  },
  {
    "statement": "The physical removal of problematic plants in fens increased the cover of fen-characteristic plants in one study.",
    "citations": [
      "1768"
    ]
  },
  {
    "statement": "The physical removal of problematic plants in fens had mixed effects on herb cover.",
    "citations": [
      "1768"
    ]
  },
  {
    "statement": "The physical removal of problematic plants in fens often reduced bryophyte and Sphagnum cover, especially in drained plots.",
    "citations": [
      "1768"
    ]
  },
  {
    "statement": "The physical removal of problematic plants in fens increased plant species richness only in a drained area.",
